import{_ as i,o as r,c as t,ae as a}from"./chunks/framework.vXWZTEWX.js";const p=JSON.parse('{"title":"Software Engineering Principles: Development Lifecycle & Programming Paradigms","description":"","frontmatter":{},"headers":[],"relativePath":"standards/lifecycle_paradigms.md","filePath":"standards/lifecycle_paradigms.md"}'),n={name:"standards/lifecycle_paradigms.md"};function o(l,e,s,c,g,d){return r(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="software-engineering-principles-development-lifecycle-programming-paradigms" tabindex="-1">Software Engineering Principles: Development Lifecycle &amp; Programming Paradigms <a class="header-anchor" href="#software-engineering-principles-development-lifecycle-programming-paradigms" aria-label="Permalink to &quot;Software Engineering Principles: Development Lifecycle &amp; Programming Paradigms&quot;">​</a></h1><p>Use these guidelines as a reference for project structure, code generation, and methodology justification.</p><h2 id="_1-software-development-life-cycle-sdlc-key-pillars" tabindex="-1">1. Software Development Life Cycle (SDLC) - Key Pillars <a class="header-anchor" href="#_1-software-development-life-cycle-sdlc-key-pillars" aria-label="Permalink to &quot;1. Software Development Life Cycle (SDLC) - Key Pillars&quot;">​</a></h2><ul><li><strong>Incremental &amp; Agile Approach:</strong> Prioritize delivering a functional MVP first and adding features in iterative cycles.</li><li><strong>Fundamental Phases:</strong> * <strong>Analysis:</strong> Clear definition of requirements (e.g., &quot;AI-driven tender validation&quot;). <ul><li><strong>Design:</strong> Architecture and UI/UX layout.</li><li><strong>Testing:</strong> Continuous verification of functionalities.</li><li><strong>Deployment:</strong> Reliable delivery to production.</li></ul></li><li><strong>Metrics for Success:</strong> Monitor Lead Time, deployment frequency, and automated test coverage.</li><li><strong>Anti-patterns to Avoid:</strong> &quot;Waterfall in disguise&quot; (no feedback), zero documentation, and lack of integration between modules.</li></ul><h2 id="_2-multi-paradigm-programming-strategy" tabindex="-1">2. Multi-Paradigm Programming Strategy <a class="header-anchor" href="#_2-multi-paradigm-programming-strategy" aria-label="Permalink to &quot;2. Multi-Paradigm Programming Strategy&quot;">​</a></h2><ul><li><strong>Object-Oriented Programming (OOP):</strong> Use for system structure and core entities (e.g., <code>Tender</code>, <code>User</code>, <code>ValidationRule</code>). Leverage Encapsulation and Polymorphism.</li><li><strong>Functional Programming:</strong> Use inside methods for data transformation (using <code>.map</code>, <code>.filter</code>, <code>.reduce</code>) to ensure clean code without side effects.</li><li><strong>Imperative Programming:</strong> Use only for specific, low-level algorithms where granular flow control is critical.</li><li><strong>Event-Driven/Reactive:</strong> Use for UI interactions and communication between backend services.</li></ul><h2 id="_3-implementation-logic" tabindex="-1">3. Implementation Logic <a class="header-anchor" href="#_3-implementation-logic" aria-label="Permalink to &quot;3. Implementation Logic&quot;">​</a></h2><ul><li><strong>Complex Domain?</strong> → Use <strong>OOP</strong>.</li><li><strong>Data Transformation/Business Rules?</strong> → Use <strong>Functional</strong>.</li><li><strong>Critical Performance Algorithm?</strong> → Use <strong>Imperative</strong>.</li></ul>',8)])])}const u=i(n,[["render",o]]);export{p as __pageData,u as default};
